"""Runtime access to the active brand. Values come from brand.json, generated by brand/apply.py."""

import json
from functools import lru_cache
from pathlib import Path

BRAND_FILE = Path(__file__).with_name("brand.json")


@lru_cache(maxsize=1)
def get_brand() -> dict:
	return json.loads(BRAND_FILE.read_text(encoding="utf-8"))
